PROJECT = Path(__file__).resolve().parent
WORKSPACE = PROJECT / 'workspace'
DEFAULT_OUT = WORKSPACE / 'artifacts/uam_system_gap_1h_20261101_v1'
DEFAULT_SOURCE = WORKSPACE / 'artifacts/uam_large_notrain_20261101_server_v1'
STEP = 1003520
SEED = 20261101
WINDOWS = (60, 120, 240)
sys.dont_write_bytecode = True
for _key in ('OMP_NUM_THREADS', 'MKL_NUM_THREADS', 'OPENBLAS_NUM_THREADS', 'NUMEXPR_NUM_THREADS'):
    os.environ[_key] = '1'


class BudgetStop(Exception):
    """本会话预算或本块预算用尽；保留已经完成的配对单元。"""


def digest(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))


def clean(value):
    if isinstance(value, dict):
        return {str(k): clean(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [clean(v) for v in value]
    if hasattr(value, 'tolist'):
        return clean(value.tolist())
    if isinstance(value, float) and not math.isfinite(value):
        return None
    return value


def allowed(path, root):
    path, root = Path(path).resolve(), Path(root).resolve()
    if not path.is_relative_to(root):
        raise RuntimeError('输出路径越过本轮独立目录：' + str(path))
    return path


def save(path, value, root):
    path = allowed(path, root)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + f'.pending_{os.getpid()}')
    temporary.write_text(json.dumps(clean(value), ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')
    os.replace(temporary, path)


def bundle():
    raw = zlib.decompress(base64.b85decode(BUNDLE_B85))
    if hashlib.sha256(raw).hexdigest() != BUNDLE_SHA256:
        raise RuntimeError('内嵌冻结代码校验失败')
    return json.loads(raw)


def check(job):
    if (Path(job['run_root']) / 'STOP_REQUESTED').exists():
        raise BudgetStop('用户请求暂停；未操作其他任务')
    if time.monotonic() >= job['deadline']:
        raise BudgetStop('本块时间预算已用尽')


def count_work(job, kind, ticks):
    # 分开记完整回放与候选模拟，供以后按一小时计算量估算；中断中的半次不充当完成量。
    stats = job['_counters']
    stats[kind] = stats.get(kind, 0) + 1
    stats['completed_simulated_minutes'] = stats.get('completed_simulated_minutes', 0) + ticks
    stats['worker_elapsed_seconds'] = time.monotonic() - stats['started_monotonic']
    if kind == 'full_episodes' or stats.get('candidate_calls', 0) % 20 == 0:
        save(job['_counter_path'], stats, job['run_root'])


def plans():
    result = []
    for seed in (1601, 1602, 1603, 1604):
        for side in ('S', 'J'):
            arm = f'{side}_PT_RAW'
            result.append(dict(case=f'PT_{side}_{seed}', family='pt', model_id=f'CORE__E1__K3__{arm}__s{seed}',
                               controller='MODEL', training_seed=seed, k=3, old_supplement=True,
                               label=f'新奖励{"单侧" if side == "S" else "联合"}_{seed}'))
    for seed in (601, 602, 603, 604):
        result.append(dict(case=f'SOURCE_K3_{seed}', family='strict', model_id=f'P2__K3__N12__UAGMC_SOURCE_L__s{seed}',
                           controller='MODEL', training_seed=seed, k=3, old_supplement=False, label=f'旧源单侧_{seed}'))
    for k in (2, 3, 4):
        result.append(dict(case=f'READY_K{k}', family='strict', model_id=f'P2__K{k}__N12__UAGMC_SOURCE_L__s601',
                           controller='READY', training_seed=None, k=k, old_supplement=False, label=f'强规则_{k}出发站'))
    result.append(dict(case='QTTI_K3', family='strict', model_id='P2__K3__N12__UAGMC_SOURCE_L__s601',
                       controller='AUTHOR_QTTI', training_seed=None, k=3, old_supplement=False, label='作者QTTI规则_3出发站'))
    assert len(result) == 16 and sum(c['old_supplement'] for c in result) == 8
    return result


def case_order(cases, phase):
    # 先保证主场景强规则、匹配的新奖励单侧/联合，再补旧源模型和机场数边界。
    priority = {'READY_K3': 0, 'QTTI_K3': 1, 'PT_J_1601': 2, 'PT_S_1601': 3,
                'SOURCE_K3_601': 4, 'READY_K2': 30, 'READY_K4': 31}
    remaining = [c for c in cases if c['case'] not in priority]
    random.Random(SEED + len(phase)).shuffle(remaining)
    position = {c['case']: i + 10 for i, c in enumerate(remaining)}
    return sorted(cases, key=lambda c: priority.get(c['case'], position.get(c['case'], 99)))


def make_bank(out, payload):
    import io
    rows = list(csv.DictReader(io.StringIO(payload['original_csv'])))
    if len(rows) != 300:
        raise RuntimeError('冻结需求不是300条')
    keys = ('origin_x', 'origin_y', 'dest_x', 'dest_y')
    original = Counter(tuple(r[k] for k in keys) for r in rows)
    bank = []
    for seed in (None, 4401, 4402):
        ods = [tuple(r[k] for k in keys) for r in rows]
        if seed is not None:
            random.Random(seed).shuffle(ods)
        changed = [dict(row, **dict(zip(keys, od))) for row, od in zip(rows, ods)]
        assert Counter(tuple(r[k] for k in keys) for r in changed) == original
        assert all({k: v for k, v in a.items() if k not in keys} == {k: v for k, v in b.items() if k not in keys}
                   for a, b in zip(rows, changed))
        name = 'original' if seed is None else f'order_{seed}'
        path = allowed(out / 'bank' / (name + '.csv'), out)
        path.parent.mkdir(parents=True, exist_ok=True)
        text = io.StringIO(newline='')
        writer = csv.DictWriter(text, fieldnames=list(rows[0])); writer.writeheader(); writer.writerows(changed)
        data = text.getvalue().encode('utf-8')
        if path.exists() and path.read_bytes() != data:
            raise RuntimeError('确认顺序已经存在不同内容，不覆盖')
        path.write_bytes(data)
        bank.append(dict(name=name, path=str(path), sha256=digest(path), confirmation=seed == 4402,
                         scope='固定到达时刻和OD多重集的顺序确认，不是新需求分布'))
    return bank


def locate_models(source, cases, payload):
    source = source.resolve()
    if not source.is_relative_to(WORKSPACE.resolve()) or source.is_symlink():
        raise RuntimeError('旧诊断输入必须是本项目workspace内的明确目录，不能为链接')
    indices = {family: read(source / f'INPUT_{family}.json') for family in ('pt', 'strict')}
    hashes, located = {}, []
    for case in cases:
        entry = indices[case['family']]
        matching = [j for j in entry['jobs'] if j['id'] == case['model_id']]
        if len(matching) != 1:
            raise RuntimeError('所需旧模型记录不唯一或缺失：' + case['model_id'])
        prior = matching[0]
        suite = Path(prior['root']).name
        model_root = source / 'input' / case['family'] / suite
        expected = {Path(r['path']).name: r['sha256'] for r in entry['extracted']
                    if '/' + case['model_id'] + '/resume/' in r['path']}
        for suffix in ('.zip', '.pkl'):
            path = model_root / 'cells' / case['model_id'] / 'resume' / f'step_{STEP:09d}{suffix}'
            if not path.is_file() or path.is_symlink() or not path.resolve().is_relative_to(source):
                raise RuntimeError('模型或归一化件缺失/路径重定向：' + str(path))
            wanted = expected.get(path.name)
            if wanted is None:
                raise RuntimeError('旧输入清单缺少对应hash：' + str(path))
            key = str(path)
            if key not in hashes:
                hashes[key] = digest(path)
            if hashes[key] != wanted:
                raise RuntimeError('旧模型文件与已经核验的输入清单不一致：' + str(path))
        runtime_matches = [r for r in entry['extracted'] if Path(r['path']).name == payload['entries'][case['family']]['name']]
        if len(runtime_matches) != 1 or runtime_matches[0]['sha256'] != payload['entries'][case['family']]['sha256']:
            raise RuntimeError('内嵌运行时与上轮真实执行版本不同')
        located.append(dict(case, task=prior['task'], model_root=str(model_root)))
    return located, hashes


def runtime(job):
    payload = bundle()
    base = types.ModuleType('hour_diag_base')
    base.__file__ = str(Path(__file__).resolve())
    sys.modules[base.__name__] = base
    exec(compile(payload['diagnostic_base'], '<frozen_diagnostic_base>', 'exec'), base.__dict__)
    base.check_pause = lambda unused: check(job)
    work = Path(job['work']); work.mkdir(parents=True, exist_ok=True)
    os.environ.update(CUDA_VISIBLE_DEVICES='', MPLCONFIGDIR=str(work / 'cache'), XDG_CACHE_HOME=str(work / 'cache'))
    data = base64.b64decode(payload['entries'][job['case']['family']]['bytes_b64'])
    entry = work / 'frozen_runtime.py'
    if entry.exists() and entry.read_bytes() != data:
        raise RuntimeError('本轮私有运行时已改变')
    entry.write_bytes(data)
    private_job = dict(id=job['case']['model_id'], family=job['case']['family'], task=job['case']['task'],
                       root=str(work / 'environment'), runtime=str(entry), out=str(work), run_root=job['run_root'])
    m = base.load_runtime(private_job, work)
    model, norm = base.load_model(m, dict(private_job, root=job['case']['model_root']))
    if next(model.policy.parameters()).device.type != 'cpu':
        raise RuntimeError('本轮明确使用CPU，不分配GPU')
    return base, m, model, norm, private_job


def rng_get(m):
    return random.getstate(), m.np.random.get_state(), m.torch.get_rng_state().clone()


def rng_set(m, state):
    random.setstate(state[0]); m.np.random.set_state(state[1]); m.torch.set_rng_state(state[2])


def fingerprint(env):
    s = env.scenario
    people = [(str(p.id), str(p.state), str(getattr(p, 'sub_state', '')), str(getattr(p, 'origin_vertiport_id', '')), float(getattr(p, 'current_timer', 0) or 0))
              for p in s.persons.persons.values()]
    planes = [(str(e.id), e.state.name, str(e.current_vertiport_id), str(getattr(e, 'target_vertiport_id', '')),
               float(e.battery_kwh), float(getattr(e, 'remaining_time', 0) or 0), tuple(map(str, e.passenger_ids))) for e in s._all_evtols.values()]
    value = dict(time=int(s.time), finished=sorted(map(str, s.finished_ids)), people=sorted(people), planes=sorted(planes),
                 queues={str(k): list(map(str, v.person_list)) for k, v in s.vertiports.vertiport_list.items()})
    return hashlib.sha256(json.dumps(value, sort_keys=True).encode()).hexdigest()


def episode(base, m, job, private, model, norm, bank, mode=None, tape=None, correction=None, forecast='BASE', capture=False):
    check(job)
    mode = mode or job['case']['controller']
    env, obs = base.env_new(m, private, bank['path'], 123)
    area = 0; counts = [0] * env.k; actions = []; ledger = []; corrections = []; decisions = []
    phase_area = Counter()
    started = time.monotonic()
    try:
        with m.torch.no_grad():
            while True:
                check(job)
                s = env.scenario
                unfinished = set(s.persons.persons) - set(s.finished_ids)
                ledger.append(dict(time=int(s.time), unfinished=len(unfinished)))
                area += ledger[-1]['unfinished']
                # 同一个人时积分分成状态占用，不用仅已完成人群的均值解释未完成回放。
                for pid in unfinished:
                    person = s.persons.persons[pid]
                    sub = str(getattr(person, 'sub_state', ''))
                    category = ('ground' if sub == 'to_vertiport' else 'wait' if sub in ('arriver_vertiport', 'wait_uam')
                                else 'flight' if sub == 'fly' else 'other')
                    phase_area[category] += 1
                active = bool(s.waiting_decisions)
                index = len(actions)
                forced = None
                if active and tape is not None:
                    if index >= len(tape):
                        raise RuntimeError('动作序列长度不足')
                    forced = (int(tape[index]), -1)
                if active and correction and index % 15 == 7:
                    current_rng = rng_get(m)
                    values = {}
                    for p in range(env.k):
                        rng_set(m, current_rng)
                        values[p] = branch(base, m, job, private, env, obs, model, norm, (p, -1),
                                           120, 'COMMITTED', forecast, mode)['snapshots']['120']['total']
                    rng_set(m, current_rng)
                    chosen = choose_passenger(base, m, private, env, obs, model, norm, mode)
                    picked = min(values, key=lambda p: (values[p], p != chosen, p))
                    forced = (picked, -1)
                    corrections.append(dict(index=index, chosen=picked, prior=chosen, costs=values))
                snap = base.physical(env, m) if active and capture else None
                obs, done, actual, _ = base.advance(m, private, env, obs, model, norm, mode, forced)
                if active:
                    counts[actual[0]] += 1; actions.append(int(actual[0]))
                    if capture:
                        decisions.append(dict(index=index, action=list(actual), **snap))
                if done:
                    break
        if tape is not None and len(actions) != len(tape):
            raise RuntimeError('回放动作数与原请求数不一致')
        metrics = base.metrics(m, private, env, counts, area)
        if sum(phase_area.values()) != area:
            raise RuntimeError('分状态人时与总人时不守恒')
        metrics['restricted_components_per_generated'] = {k: phase_area[k] / max(1, metrics['generated'])
                                                          for k in ('ground', 'wait', 'flight', 'other')}
        metrics['component_note'] = '同一截止边界的状态占用积分，四项之和严格等于RPT；不是原time_stats的已完成人均值'
        count_work(job, 'full_episodes', len(ledger))
        return dict(metrics=metrics, actions=actions, ledger=ledger,
                    decisions=decisions, corrections=corrections, wall_seconds=time.monotonic() - started,
                    new_training_transitions=0)
    finally:
        env.close()


def choose_passenger(base, m, private, env, obs, model, norm, mode):
    if mode == 'READY':
        return base.ready(env, m)
    if private['family'] == 'strict':
        if mode.startswith('AUTHOR_'):
            name = mode.split('_', 1)[1]
            if not hasattr(env, '_diag_authors'):
                env._diag_authors = {}
            if name not in env._diag_authors:
                env._diag_authors[name] = m.AuthorFunctions(name)
            return int(m.adapter_decision(env.scenario, env.k, env._diag_authors[name], m.np)[0])
        return int(model.predict(norm.normalize_obs(obs.copy()), deterministic=True)[0])
    return int(model.policy.sample_passenger(m.torch.as_tensor(norm.normalize_obs(obs[None]), device='cpu'), True)[0][0])


def branch(base, m, job, private, template, obs, model, norm, action, horizon, scope, continuation, mode):
    check(job)
    env = base.clone_env(template); current = obs.copy()
    initial = set(env.scenario.persons.persons)
    focal = env.scenario.waiting_decisions[0] if env.scenario.waiting_decisions else None
    if scope == 'COMMITTED':
        base.hide_future(env)
    elif scope != 'REALIZED':
        raise RuntimeError('未知信息边界')
    totals = [0, 0, 0]; snapshots = {}; ticks = 0
    actual_mode = mode if continuation == 'BASE' else 'READY'
    try:
        with m.torch.no_grad():
            for offset in range(horizon):
                check(job)
                s = env.scenario; unfinished = set(s.persons.persons) - set(s.finished_ids)
                totals[0] += int(focal in unfinished)
                totals[1] += len((unfinished & initial) - {focal})
                totals[2] += len(unfinished - initial)
                # 当前动作仍通过原控制器执行，只有之后的分钟才切换共同后续策略。
                current, done, _, _ = base.advance(m, private, env, current, model, norm, mode if offset == 0 else actual_mode,
                                                 action if offset == 0 else None)
                ticks += 1
                if ticks in WINDOWS or ticks == horizon or done:
                    snapshots[str(ticks)] = dict(total=sum(totals), focal=totals[0], existing=totals[1], future=totals[2],
                                                 finished=len(set(s.finished_ids)), observed_ticks=ticks)
                if done:
                    break
        for h in WINDOWS:
            if h <= horizon and str(h) not in snapshots:
                snapshots[str(h)] = dict(snapshots[str(ticks)], clipped=True)
        count_work(job, 'candidate_calls', ticks)
        return dict(snapshots=snapshots, ticks=ticks)
    finally:
        env.close()


def cache_episode(base, m, job, private, model, norm, bank, name, mode=None, correction=None, forecast='BASE'):
    path = Path(job['run_root']) / 'cases' / job['case']['case'] / bank['name'] / (name + '.json')
    cached = path.exists()
    value = read(path) if cached else episode(base, m, job, private, model, norm, bank, mode=mode, correction=correction, forecast=forecast, capture=name == 'BASE')
    if bank['name'] == 'original' and name == 'BASE':
        source = Path(job['source_root'])
        case = job['case']
        if case['controller'] == 'MODEL':
            old = source / 'baseline' / case['family'] / case['model_id'] / 'original_s123.json'
        else:
            old = source / 'rules' / case['family'] / case['model_id'] / ('original_' + case['controller'] + '.json')
        if not old.exists():
            raise RuntimeError('历史原顺序核验记录缺失')
        old_metrics = read(old)['metrics']
        for key in ('generated', 'finished', 'ATT_completed_only', 'restricted_person_time_per_generated'):
            a, b = value['metrics'].get(key), old_metrics.get(key)
            if a is None or b is None:
                if a != b:
                    raise RuntimeError('历史复评缺失值不一致：' + key)
            elif abs(float(a) - float(b)) > 1e-6:
                raise RuntimeError('原顺序历史复评不一致：' + key)
    if not cached:
        save(path, value, job['run_root'])
    return value


def metrics_key(metrics):
    return -int(metrics['finished']), float(metrics['restricted_person_time_per_generated'])


def repair_tail(base, m, job, private, model, norm, bank, source_name, source, mode):
    path = Path(job['run_root']) / 'cases' / job['case']['case'] / bank['name'] / ('TAIL_' + source_name + '.json')
    if path.exists():
        return read(path)
    tape = source['actions']
    audit = episode(base, m, job, private, model, norm, bank, mode=mode, tape=tape)
    if abs(audit['metrics']['restricted_person_time_per_generated'] - source['metrics']['restricted_person_time_per_generated']) > 1e-6:
        raise RuntimeError('固定乘客序列不能复现原回放，停止尾批解释')
    pool = []
    for station in range(job['case']['k']):
        ids = [i for i, action in enumerate(tape) if action == station]
        remainder = len(ids) % 4
        if remainder:
            pool.extend(ids[-remainder:])
    candidates = [dict(target=None, changed=0, metrics=audit['metrics'], actions=tape)]
    for target in range(job['case']['k']) if pool else ():
        proposal = list(tape)
        for index in pool:
            proposal[index] = target
        trial = episode(base, m, job, private, model, norm, bank, mode=mode, tape=proposal)
        candidates.append(dict(target=target, changed=sum(a != b for a, b in zip(tape, proposal)),
                               metrics=trial['metrics'], actions=proposal))
    best = min(candidates, key=lambda x: (metrics_key(x['metrics']), x['target'] is not None))
    result = dict(source=source_name, original=source['metrics'], trials=candidates, best=best,
                  privileged_hindsight=True, selection='先服务完成数、再固定边界人时，不是在线新算法')
    save(path, result, job['run_root'])
    return result


def pair_list(tape, seed, maximum=24):
    # 正常运营阶段只交换已有不同选站，固定各站总分配人数；不选最后60个乘客。
    limit = min(240, len(tape))
    pool = [(i, j) for i in range(limit) for j in range(i + 1, limit) if tape[i] != tape[j]]
    rng = random.Random(seed); rng.shuffle(pool)
    return pool[:maximum]


def search_swaps(base, m, job, private, model, norm, bank, anchor):
    path = Path(job['run_root']) / 'cases' / job['case']['case'] / bank['name'] / 'SWAPS.json'
    existing = read(path) if path.exists() else None
    tape = anchor['best']['actions']
    pairs = pair_list(tape, SEED + int(job['case']['task']['seed']) + sum(map(ord, bank['name'])))
    if existing and existing['pairs'] != [list(p) for p in pairs]:
        raise RuntimeError('交换提案表改变，不混用部分结果')
    rows = existing['trials'] if existing else []
    for index in range(len(rows), len(pairs)):
        check(job)
        i, j = pairs[index]; proposal = list(tape)
        proposal[i], proposal[j] = proposal[j], proposal[i]
        if Counter(proposal) != Counter(tape):
            raise RuntimeError('交换改变了各站最终分配人数')
        trial = episode(base, m, job, private, model, norm, bank, tape=proposal)
        rows.append(dict(pair=[i, j], metrics=trial['metrics'], wall_seconds=trial['wall_seconds']))
        save(path, dict(anchor=anchor['best']['metrics'], pairs=pairs, trials=rows, complete=False,
                        count_preserved=True, privileged_hindsight=True), job['run_root'])
    eligible = [dict(pair=None, metrics=anchor['best']['metrics'])] + [r for r in rows if r['metrics']['finished'] >= anchor['best']['metrics']['finished']]
    best = min(eligible, key=lambda r: (metrics_key(r['metrics']), r['pair'] is not None))
    result = dict(anchor=anchor['best']['metrics'], pairs=pairs, trials=rows, best=best, complete=True,
                  count_preserved=True, privileged_hindsight=True, search_sufficient=bool(pairs),
                  boundary='只找到有限单对交换的可行改善，不是全局最优，也不严格剥离所有尾部等待')
    save(path, result, job['run_root'])
    return result


def sample_indices(seed, trace):
    rng = random.Random(SEED + seed + sum(map(ord, trace)))
    large, small = [], []
    for start in (0, 100, 200):
        chosen = rng.sample(list(range(start, start + 100)), 6)
        large.extend(chosen); small.extend(chosen[:2])
    return sorted(large), sorted(small)


def action_candidates(base, m, job, private, env, obs, model, norm, original, state_rng, small=False):
    if small or not getattr(env, 'joint', False):
        return [(p, -1) for p in range(env.k)]
    result = [tuple(original)]
    for p in range(env.k):
        check(job); rng_set(m, state_rng)
        probe = base.clone_env(env)
        try:
            pending = probe.prepare_step(p)
            valid = [i for i, value in enumerate(pending[probe.schema.return_mask]) if value > .5]
            for a in valid:
                if (p, a) not in result:
                    result.append((p, a))
            # 完成探针自己的分钟，避免将暂停中的generator留到后续状态。
            probe.finish_step(valid[0])
        finally:
            probe.close()
    rng_set(m, state_rng)
    return result


def branches_for_case(base, m, job, private, model, norm, bank, small):
    phase = 'A_BRANCHES' if small else 'C_BRANCHES'
    folder = Path(job['run_root']) / 'cases' / job['case']['case'] / bank['name'] / phase
    baseline = cache_episode(base, m, job, private, model, norm, bank, 'BASE')
    selected = sample_indices(job['case']['task']['seed'], bank['name'])[int(small)]
    save(folder / 'SAMPLE.json', dict(indices=selected, sampling='按乘客序号早中晚等量随机，候选标签前固定',
                                     nested_subset=small), job['run_root'])
    if len(baseline['decisions']) != 300:
        raise RuntimeError('基线乘客决策数不是300，不猜测抽样位置')
    env, obs = base.env_new(m, private, bank['path'], 123)
    index = 0; completed = 0
    try:
        with m.torch.no_grad():
            while True:
                check(job)
                if env.scenario.waiting_decisions:
                    if index in selected:
                        target = folder / f'state_{index:03d}.json'
                        if target.exists():
                            completed += 1
                        else:
                            rec = baseline['decisions'][index]
                            original = tuple(rec['action']); state_rng = rng_get(m)
                            before = fingerprint(env)
                            candidates = action_candidates(base, m, job, private, env, obs, model, norm, original, state_rng, small)
                            rows = []
                            continuations = ['BASE'] if job['case']['controller'] == 'READY' else ['BASE', 'READY']
                            for continuation in continuations:
                                for scope in (('REALIZED', 'COMMITTED') if small else ('REALIZED',)):
                                    for action in candidates:
                                        rng_set(m, state_rng)
                                        value = branch(base, m, job, private, env, obs, model, norm, action,
                                                       240, scope, continuation, job['case']['controller'])
                                        rows.append(dict(action=list(action), continuation=continuation, scope=scope, **value))
                            # 原动作在原后续策略下必须与原轨迹积分逐项一致。
                            if small:
                                reference_action = [int(original[0]), -1]
                            else:
                                reference_action = list(original)
                            ref = next(r for r in rows if r['action'] == reference_action and r['continuation'] == 'BASE' and r['scope'] == 'REALIZED')
                            for h in WINDOWS:
                                expected = sum(r['unfinished'] for r in baseline['ledger'] if rec['time'] <= r['time'] < rec['time'] + h)
                                if ref['snapshots'][str(h)]['total'] != expected:
                                    raise RuntimeError('克隆参考成本不等于原轨迹，不生成候选标签')
                            # 共同READY后续也重复核验，避免把换后续策略的成本当原轨迹成本。
                            if 'READY' in continuations:
                                rng_set(m, state_rng)
                                duplicate = branch(base, m, job, private, env, obs, model, norm, reference_action,
                                                   240, 'REALIZED', 'READY', job['case']['controller'])
                                ref2 = next(r for r in rows if r['action'] == reference_action and r['continuation'] == 'READY' and r['scope'] == 'REALIZED')
                                if duplicate['snapshots'] != ref2['snapshots']:
                                    raise RuntimeError('共同后续策略的克隆复核不一致')
                            if fingerprint(env) != before:
                                raise RuntimeError('分支污染原环境；停止此格')
                            rng_set(m, state_rng)
                            save(target, dict(index=index, time=rec['time'], original=list(original), physical=base.physical(env, m),
                                              rows=rows, original_reference=reference_action, clone_protocol=base.CLONE_PROTOCOL,
                                              all_references_passed=True, local_not_global=True), job['run_root'])
                            completed += 1
                    index += 1
                obs, done, _, _ = base.advance(m, private, env, obs, model, norm, job['case']['controller'])
                if done:
                    break
        return dict(trace=bank['name'], states=completed, phase=phase)
    finally:
        env.close()


def worker(path):
    job = read(path); check(job)
    job['_counters'] = dict(started_monotonic=time.monotonic(), started_at=time.time(),
                            completed_work_only=True, full_episodes=0, candidate_calls=0)
    job['_counter_path'] = str(Path(job['out']) / f'COUNTERS_{os.getpid()}_{int(time.time())}.json')
    print('[开始单元]', job['phase'], job['case']['case'], flush=True)
    base, m, model, norm, private = runtime(job)
    policy_before = {k: v.detach().cpu().clone() for k, v in model.policy.state_dict().items()}
    completed = []
    for bank in job['bank']:
        check(job)
        initial = cache_episode(base, m, job, private, model, norm, bank, 'BASE')
        if job['phase'] == 'A_旧证据补充':
            ready = cache_episode(base, m, job, private, model, norm, bank, 'READY', mode='READY')
            repair_tail(base, m, job, private, model, norm, bank, 'BASE', initial, job['case']['controller'])
            repair_tail(base, m, job, private, model, norm, bank, 'READY', ready, 'READY')
            for forecast in ('BASE', 'READY'):
                name = 'KNOWN_' + forecast
                corrected = cache_episode(base, m, job, private, model, norm, bank, name, correction=True, forecast=forecast)
                repair_tail(base, m, job, private, model, norm, bank, name, corrected, job['case']['controller'])
            completed.append(branches_for_case(base, m, job, private, model, norm, bank, True))
        elif job['phase'] == 'B_系统可行改善':
            anchor = repair_tail(base, m, job, private, model, norm, bank, 'BASE', initial, job['case']['controller'])
            value = search_swaps(base, m, job, private, model, norm, bank, anchor)
            completed.append(dict(trace=bank['name'], swaps=len(value['trials'])))
        elif job['phase'] == 'C_决策过程归因':
            completed.append(branches_for_case(base, m, job, private, model, norm, bank, False))
        else:
            raise RuntimeError('未知诊断阶段')
        print('[完成顺序]', bank['name'], completed[-1], flush=True)
    for key, value in model.policy.state_dict().items():
        if not m.torch.equal(value.detach().cpu(), policy_before[key]):
            raise RuntimeError('冻结策略参数发生改变')
    save(job['_counter_path'], job['_counters'], job['run_root'])
    save(Path(job['out']) / 'END.json', dict(case=job['case'], phase=job['phase'], completed=completed,
         policy_parameters_unchanged=True, new_training_transitions=0, finished_at=time.time()), job['run_root'])


def resource_check(out):
    disk = shutil.disk_usage(out.parent)
    cpus = os.cpu_count() or 1
    load = os.getloadavg()[0] if hasattr(os, 'getloadavg') else None
    mem_available = None
    if Path('/proc/meminfo').exists():
        for line in Path('/proc/meminfo').read_text().splitlines():
            if line.startswith('MemAvailable:'):
                mem_available = int(line.split()[1]) * 1024
    result = dict(cpu_count=cpus, load_average_1m=load, memory_available_bytes=mem_available,
                  disk_free_bytes=disk.free, workers=2, threads_per_worker=1, gpu_needed=False,
                  live_gpu_checked_by_agent=False, note='CPU诊断；用户在启动前自行查看top和nvidia-smi')
    if disk.free < 2 * 1024**3 or (mem_available is not None and mem_available < 3 * 1024**3):
        raise RuntimeError('本轮资源不足；不启动worker，不影响其他任务')
    if load is not None and load / cpus > .8:
        raise RuntimeError('共享CPU当前负载过高；请稍后再启动本轮任务')
    return result


def launch(job, retry):
    folder = Path(job['out']); folder.mkdir(parents=True, exist_ok=True)
    if (folder / 'END.json').exists():
        return dict(case=job['case']['case'], status='EXISTING')
    if (folder / 'FAILED.json').exists() and not retry:
        return dict(case=job['case']['case'], status='FAILED_SKIPPED')
    try:
        check(job)
    except BudgetStop as error:
        return dict(case=job['case']['case'], status='BUDGET_SKIPPED', reason=str(error))
    save(folder / 'JOB.json', job, job['run_root'])
    started = time.monotonic()
    with (folder / 'worker.log').open('a', encoding='utf-8') as stream:
        proc = subprocess.Popen([sys.executable, '-B', '-u', str(Path(__file__).resolve()), '--worker', str(folder / 'JOB.json')],
                                stdout=stream, stderr=subprocess.STDOUT, cwd=folder)
        try:
            code = proc.wait(timeout=max(1., min(900., job['deadline'] - time.monotonic() + 8.)))
        except subprocess.TimeoutExpired:
            # 只终止此处新建、由Popen句柄明确拥有的诊断子进程，不匹配或触碰其他Python。
            proc.terminate()
            try:
                proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                proc.kill(); proc.wait()
            code = 130
    result = dict(case=job['case']['case'], status='COMPLETE' if code == 0 else ('BUDGET_PARTIAL' if code == 130 else 'FAILED'),
                  elapsed_seconds=time.monotonic() - started, exit_code=code)
    save(folder / ('ATTEMPT_END.json' if code in (0, 130) else 'FAILED.json'), result, job['run_root'])
    return result


def csv_output(out, name, rows):
    if not rows:
        return
    fields = list(dict.fromkeys(k for row in rows for k in row))
    with allowed(out / name, out).open('w', encoding='utf-8-sig', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=fields); writer.writeheader()
        writer.writerows({k: json.dumps(v, ensure_ascii=False) if isinstance(v, (dict, list)) else v for k, v in row.items()} for row in rows)


def summarize(out, manifest, sessions):
    baselines, repairs, swaps, branches, corrections = [], [], [], [], []
    for case in manifest['cases']:
        meta = {k: case[k] for k in ('case', 'family', 'controller', 'training_seed', 'k', 'label')}
        folder = out / 'cases' / case['case']
        for bank in manifest['bank']:
            trace = bank['name']; here = folder / trace
            for name in ('BASE', 'READY', 'KNOWN_BASE', 'KNOWN_READY'):
                path = here / (name + '.json')
                if not path.exists():
                    continue
                d = read(path); e = d['metrics']
                row = dict(meta, trace=trace, mode=name, rpt=e['restricted_person_time_per_generated'],
                           completion=e['completion'], finished=e['finished'], full=e['full'], att=e['ATT'],
                           wall_seconds=d['wall_seconds'])
                baselines.append(row)
                if name.startswith('KNOWN'):
                    corrections.append(row)
                tail = here / ('TAIL_' + name + '.json')
                if tail.exists():
                    r = read(tail); best = r['best']['metrics']
                    repairs.append(dict(meta, trace=trace, mode=name, base_rpt=row['rpt'], repaired_rpt=best['restricted_person_time_per_generated'],
                                        repaired_finished=best['finished'], repaired_full=best['full'], repaired_att=best['ATT'],
                                        gain=row['rpt'] - best['restricted_person_time_per_generated'], privileged_hindsight=True))
            path = here / 'SWAPS.json'
            if path.exists():
                d = read(path)
                if d.get('complete'):
                    a, b = d['anchor'], d['best']['metrics']
                    swaps.append(dict(meta, trace=trace, proposals=len(d['trials']), sufficient=d['search_sufficient'],
                                      anchor_rpt=a['restricted_person_time_per_generated'], best_rpt=b['restricted_person_time_per_generated'],
                                      gain=a['restricted_person_time_per_generated'] - b['restricted_person_time_per_generated'],
                                      anchor_finished=a['finished'], best_finished=b['finished'], full=b['full'], att=b['ATT'],
                                      **{part + '_occupancy_gain': a['restricted_components_per_generated'][part] - b['restricted_components_per_generated'][part]
                                         for part in ('ground', 'wait', 'flight', 'other')},
                                      privileged_hindsight=True, count_preserved=True))
            for stage in ('A_BRANCHES', 'C_BRANCHES'):
                for path in sorted((here / stage).glob('state_*.json')):
                    d = read(path)
                    for continuation in sorted({r['continuation'] for r in d['rows']}):
                        actual = {tuple(r['action']): r for r in d['rows'] if r['scope'] == 'REALIZED' and r['continuation'] == continuation}
                        known = {tuple(r['action']): r for r in d['rows'] if r['scope'] == 'COMMITTED' and r['continuation'] == continuation}
                        original = tuple(d['original_reference'])
                        for h in WINDOWS:
                            ref = actual[original]['snapshots'][str(h)]
                            score = lambda a: (actual[a]['snapshots'][str(h)]['total'], a != original, a)
                            winner = min(actual, key=score); best = actual[winner]['snapshots'][str(h)]
                            winners = {a for a in actual if actual[a]['snapshots'][str(h)]['total'] == best['total']}
                            selfish = {a for a in actual if actual[a]['snapshots'][str(h)]['focal'] == min(r['snapshots'][str(h)]['focal'] for r in actual.values())}
                            value = dict(meta, trace=trace, stage=stage, index=d['index'], time=d['time'], continuation=continuation,
                                         horizon=h, candidates=len(actual), reference_cost=ref['total'], offline_local_gain=ref['total']-best['total'],
                                         focal_gain=ref['focal']-best['focal'], existing_gain=ref['existing']-best['existing'], future_gain=ref['future']-best['future'],
                                         every_system_best_harms_focal=all(actual[a]['snapshots'][str(h)]['focal'] > ref['focal'] for a in winners),
                                         personal_system_optima_disjoint=not bool(winners & selfish))
                            fixed_air = [a for a in actual if a[1] == original[1]]
                            fixed_passenger = [a for a in actual if a[0] == original[0]]
                            p_gain = ref['total'] - min(actual[a]['snapshots'][str(h)]['total'] for a in fixed_air)
                            a_gain = ref['total'] - min(actual[a]['snapshots'][str(h)]['total'] for a in fixed_passenger)
                            coordinate_valid = stage == 'C_BRANCHES' and case['task'].get('control') == 'J3'
                            value.update(best_actions=[list(a) for a in sorted(winners)],
                                         explicit_joint_coordinate_comparison=coordinate_valid,
                                         passenger_change_fixed_air_gain=p_gain if coordinate_valid else None,
                                         aircraft_change_fixed_passenger_gain=a_gain if coordinate_valid else None,
                                         joint_beyond_best_single_gain=value['offline_local_gain']-max(p_gain, a_gain) if coordinate_valid else None)
                            short = {a for a in actual if actual[a]['snapshots']['60']['total'] == min(r['snapshots']['60']['total'] for r in actual.values())}
                            long = {a for a in actual if actual[a]['snapshots']['240']['total'] == min(r['snapshots']['240']['total'] for r in actual.values())}
                            value['optimal_sets_60_240_disjoint'] = not bool(short & long)
                            if known:
                                picked = min(known, key=lambda a: (known[a]['snapshots'][str(h)]['total'], a != original, a))
                                value['known_forecast_realized_gain'] = ref['total'] - actual[picked]['snapshots'][str(h)]['total']
                            branches.append(value)
    for name, rows in [('01_完整回放.csv', baselines), ('02_同等尾批处理.csv', repairs), ('03_保人数交换.csv', swaps),
                       ('04_候选成本归因.csv', branches), ('05_完整预测修正.csv', corrections)]:
        csv_output(out, name, rows)
    checks = {case['case']: {phase: (out / 'jobs' / phase / case['case'] / 'END.json').exists()
                            for phase in ('A_旧证据补充', 'B_系统可行改善', 'C_决策过程归因')
                            if phase != 'A_旧证据补充' or case['old_supplement']} for case in manifest['cases']}
    complete = all(all(v.values()) for v in checks.values())
    weights_unchanged = all(Path(p).is_file() and digest(p) == h for p, h in manifest['input_hashes'].items())
    if not weights_unchanged:
        raise RuntimeError('输入模型文件发生改变，不发布完整结论')
    lines = ['# 一小时无训练诊断：先看这些结果', '',
             '本页只汇总真实已完成单元；没有新训练，不自动选择新方法。',
             f"会话状态：{'完整完成' if complete else '部分完成，缺项必须保留'}。详细任务见SESSION_END.json。", '',
             '## 一、强规则也做同样尾批处理后，还差多少？', '',
             '看02_同等尾批处理.csv；必须按同一请求顺序、同一运行合同比较。READY重复出现不代表多个训练seed。', '',
             '## 二、不改变各站最终人数，只换正常运营阶段的分流，能否更好？', '',
             '| 控制器案例 | 请求顺序 | 提案数 | 找到的额外减少，分钟/人 | 送完人数 |',
             '| --- | --- | ---: | ---: | ---: |']
    for r in swaps:
        lines.append(f"| {r['label']} | {r['trace']} | {r['proposals']} | {r['gain']:.3f} | {r['best_finished']} |")
    lines += ['', '交换使用完整动作序列，是离线可行改善证据，不是在线方法或全局最优。保持各站总人数，并不等于严格消除了所有尾部等待影响。',
              '03表分解地面、候机、飞行和其他状态的占用积分。若收益主要来自地面路径缩短，不能改称时序协调收益；候机下降也仍需候选分支证据支持。', '',
              '## 三、问题只在UAGMC，还是强规则也出现？', '',
              '看04_候选成本归因.csv，按案例、后续策略、窗口和训练seed分别读。局部人分钟不能加成整场收益；共同READY后续用于检查结论是否依赖原模型的后续错误。', '',
              '## 四、后续训练怎样分支？', '',
              '- 若差距主要被同等尾批处理消除：先补服务收尾和评价合同，不开时序/WM大训练。',
              '- 若只有源模型有大损失而READY没有：优先完成现有50M与强基线解释，不包装成交通系统共同缺口。',
              '- 若强规则和新奖励模型均有非尾批、跨顺序的可行改善：形成交通决策问题候选，再检索最近邻并只对未解释机制做小训练。',
              '- 若更换后续策略后局部差距消失或反转：优先查原策略后续误差，不能把局部标签直接训练成新Q。',
              '- 若无新到达预测仍反复选错：不直接教网络复刻这些标签；需求不确定性的合法预测价值仍未确认。',
              '- 若不同案例、顺序或seed方向反转：维持未决，先看条件分组；不立即扩方法池。', '',
              '以上是人工复核分支，不是程序自动宣布某个原因成立，也不会自动启动训练。', '',
              '## 名词', '', 'RPT：固定截止时的人均累计耗时；ATT：全员完成后的平均旅时，未完成时保持空。',
              'BASE：之后继续当前控制器；READY：之后统一用强规则；REALIZED：真实请求逐步出现的事后回放；COMMITTED：假设不再来新请求的近似。',
              '确认顺序4402在脚本固定后生成，只检验固定需求多重集内的顺序，不是新分布。']
    (out / '诊断结果_白话说明.md').write_text('\n'.join(lines), encoding='utf-8')
    body = '<pre style="white-space:pre-wrap;line-height:1.9">' + html.escape('\n'.join(lines)) + '</pre>'
    (out / '诊断结果_白话说明.html').write_text('<!doctype html><meta charset="utf-8"><title>一小时无训练诊断</title><main style="max-width:1100px;margin:30px auto;font:16px system-ui">' + body + '</main>', encoding='utf-8')
    status = 'COMPLETE' if complete else 'PARTIAL'
    work_counts = [read(p) for p in (out / 'jobs').rglob('COUNTERS_*.json')]
    save(out / 'SESSION_END.json', dict(status=status, tasks=checks, sessions=sessions, weights_unchanged=weights_unchanged,
         counts=dict(full_records=len(baselines), tail_records=len(repairs), swap_records=len(swaps), local_window_rows=len(branches)),
         completed_work_lower_bound={k: sum(r.get(k, 0) for r in work_counts)
                                     for k in ('full_episodes', 'candidate_calls', 'completed_simulated_minutes')},
         new_training_transitions=0, no_automatic_training=True), out)
    package = out / 'uam_system_gap_1h_20261101_DATAONLY.tar.gz'
    with tarfile.open(package, 'w:gz') as tar:
        for p in sorted(out.rglob('*')):
            relative = p.relative_to(out)
            if not p.is_file() or p == package or relative.parts[0] in ('work', 'cache') or '.pending_' in p.name:
                continue
            tar.add(p, arcname='uam_system_gap_1h_20261101/' + relative.as_posix(), recursive=False)
        tar.add(Path(__file__).resolve(), arcname='code/' + Path(__file__).name, recursive=False)
    print('[数据包]', package, package.stat().st_size, 'bytes', flush=True)
    return status


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--out', default=str(DEFAULT_OUT))
    parser.add_argument('--source-root', default=str(DEFAULT_SOURCE))
    parser.add_argument('--wall-seconds', type=int, default=3600)
    parser.add_argument('--workers', type=int, default=2)
    parser.add_argument('--resume', action='store_true')
    parser.add_argument('--retry-failed', action='store_true')
    parser.add_argument('--worker')
    args = parser.parse_args()
    if args.worker:
        try:
            worker(args.worker)
        except BudgetStop as error:
            print('[保留部分结果]', str(error), flush=True); raise SystemExit(130)
        return
    started = time.monotonic()
    if not 300 <= args.wall_seconds <= 3600:
        raise RuntimeError('本入口每次会话预算必须在300至3600秒内；续跑需显式--resume')
    out = Path(args.out).resolve()
    if not out.is_relative_to((WORKSPACE / 'artifacts').resolve()) or out == WORKSPACE / 'artifacts':
        raise RuntimeError('本轮输出必须是项目workspace/artifacts下的独立子目录')
    if out.exists() and not args.resume:
        raise RuntimeError('输出目录已存在，请--resume或使用新的--out，不覆盖旧记录')
    out.mkdir(parents=True, exist_ok=True)
    import fcntl
    lock = (out / 'PARENT.lock').open('a+')
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        raise RuntimeError('同一输出目录已有自己的诊断父进程，不重复启动')
    payload = bundle(); source = Path(args.source_root).resolve()
    cases, hashes = locate_models(source, plans(), payload)
    bank = make_bank(out, payload)
    manifest_path = out / 'MANIFEST.json'
    contract = dict(version=VERSION, script_sha256=digest(__file__), source_root=str(source), cases=cases,
                    bank=bank, input_hashes=hashes, windows=WINDOWS, full_states_per_case=54,
                    supplement_states_per_case=18, swap_proposals_per_episode=24, new_training_transitions=0,
                    literature=payload['literature'], training_branches=payload['training_branches'],
                    phase_time_caps_fraction=dict(A=.30, B=.60, C=1.0), inference_only=True)
    if manifest_path.exists() and read(manifest_path) != clean(contract):
        raise RuntimeError('续跑合同、入口或输入hash不同，拒绝静默混合')
    save(manifest_path, contract, out)
    save(out / 'RESOURCE_CHECK.json', resource_check(out), out)
    sessions = read(out / 'SESSIONS.json') if (out / 'SESSIONS.json').exists() else []
    session = dict(number=len(sessions) + 1, started_at=time.time(), wall_budget_seconds=args.wall_seconds, results=[])
    sessions.append(session)
    save(out / 'SESSIONS.json', sessions, out)
    print('[启动] 冻结策略诊断；最多两名CPU工人，新训练0步；会话上限', args.wall_seconds, '秒', flush=True)
    # 为三块分别留时间，避免旧证据或完整交换搜索挤掉最后的决策过程诊断。
    hard = started + args.wall_seconds - 90
    stages = [('A_旧证据补充', [c for c in cases if c['old_supplement']], min(hard, started + args.wall_seconds * .30)),
              ('B_系统可行改善', cases, min(hard, started + args.wall_seconds * .60)), ('C_决策过程归因', cases, hard)]
    for phase, selected, deadline in stages:
        order = case_order(selected, phase)
        save(out / 'progress.json', dict(phase=phase, finished_in_phase=0, phase_total=len(order),
             elapsed_seconds=time.monotonic()-started, new_training_transitions=0,
             note='按已完成案例更新；单个案例内部进度见对应worker.log'), out)
        jobs = [dict(case=c, bank=bank, phase=phase, deadline=deadline, run_root=str(out), source_root=str(source),
                     out=str(out / 'jobs' / phase / c['case']), work=str(out / 'work' / phase / c['case'])) for c in order]
        with ThreadPoolExecutor(max_workers=min(2, max(1, args.workers))) as pool:
            futures = {pool.submit(launch, j, args.retry_failed): j for j in jobs}
            for future in as_completed(futures):
                j = futures[future]
                try:
                    result = future.result()
                except Exception as error:
                    result = dict(case=j['case']['case'], status='FAILED', error=repr(error))
                session['results'].append(dict(phase=phase, **result))
                save(out / 'progress.json', dict(phase=phase, finished_in_phase=sum(r['phase'] == phase for r in session['results']),
                     phase_total=len(jobs), last=result, elapsed_seconds=time.monotonic() - started,
                     remaining_seconds=max(0, hard-time.monotonic()), new_training_transitions=0), out)
                print('[进度]', phase, result, flush=True)
        save(out / 'SESSIONS.json', sessions, out)
    session['ended_at'] = time.time(); session['elapsed_seconds'] = time.monotonic() - started
    save(out / 'SESSIONS.json', sessions, out)
    status = summarize(out, contract, sessions)
    print('[结束]', status, '本次秒数', round(time.monotonic()-started, 1), '新训练0步', flush=True)


if __name__ == '__main__':
    try:
        main()
    except Exception:
        traceback.print_exc(); raise SystemExit(1)
